var syntaxFastSchemaValid = func() bool {
	for typ, fields := range syntaxFastTypes {
		if typ.NumField() != len(fields) {
			return false
		}
		for i, field := range fields {
			f := typ.Field(i)
			if f.Name+":"+f.Type.String() != field {
				return false
			}
		}
	}
	return true
}()

func FastSyntaxCopiesAvailable() bool { return syntaxFastSchemaValid }
